  const re=()=>{save();bidRender()};B.querySelector('#bdBack').onclick=()=>{cur=null;bidRender()};B.querySelector('#bdTk').onclick=()=>{AME.open('tko');openProject(cur._id,cur)};B.querySelector('#bdXls').onclick=bidXls;B.querySelector('#bdLib').onclick=libDlg;B.querySelector('#bdFx').onclick=()=>{BFX=!BFX;try{localStorage.setItem('bidFx',BFX?'1':'0')}catch(e){}bidRender()};B.querySelector('#bdQbp').onchange=e=>{const f=e.target.files[0];if(f)importQbp(f)};
